/// <summary>
/// Logic block used to register images for items
/// </summary>
class MwmsLogicBlockRegisterItemImage extends MWmsLogicBlock implements TFMLogicBlockDataCollectionInterface
{
    InventTable             inventTable;
    InventDim               inventDim;
    Common                  common;

}

Method.Source:
public static MwmsLogicBlockRegisterItemImage Construct()
{
    return new MwmsLogicBlockRegisterItemImage();
}

protected void new()
{
    TFMLogicComponentDimensions comp = new TFMLogicComponentDimensions();
    super();
    comp.parmDisableStorageDim(true);
    comp.parmDisableTrackingDim(true);
    components.addComponent(comp);

    categories.add("@TaskletMobileWMS:Image");
}

public TFMRegistrationCollectors registrationCollectors()
{
    TFMRegistrationCollectors               ret = components.getCollectors();
    TFMRegistrationCollectorImageCapture    imgCapt = new TFMRegistrationCollectorImageCapture(100,extendedTypeStr(ImageDataString),"@SYS59132","@SYS59132",'');
    ret.addCollector(imgCapt);
    return ret;
}

public TFMReferenceDataConfiguration headerFieldsNeeded()
{
    refConf = components.getHeaders();
    return refConf;
}

/// <summary>
/// Name of the block Type.
/// </summary>
/// <returns>Name of the block</returns>
public Name blockName()
{
    return "@MobileWms:RegisterItemImage";
}

public TFMPostResponseData post()
{
    TFMPostResponseData                 result = TFMPostResponseData::Construct();
    ItemId                              itemid;
    InventDimCombination                iDimCom;
    TFMRequestItemAndDimensionElement   postRequest = request.convertToOtherRequestType(classStr(TFMRequestItemAndDimensionElement));
    str                                 mediaIDs = postRequest.getFieldValue(extendedTypeStr(ImageDataString));

    itemid = postRequest.parmItemId();
    inventDim = InventDim::findOrCreate(postRequest.parmInventDim());

    iDimCom = InventDimCombination::find(itemid,inventDim.inventDimId);

    if (mediaIDs)
    {
        common = iDimCom;
        if (common == null)
        {
            common = InventTable::find(itemid);
        }
        TFMMediaQueue::AddMap2Queue(common, TFMMediaQueue::separateIDsAndComments(mediaIDs), postRequest.parmdeviceID());
    }

    result.parmResponseText("@TFM:MEL9");
    return result;
}
